-- Synthetic contract for P5 tests before P2 is merged. Not production DDL.
create table public.partners(id uuid primary key default gen_random_uuid(),co integer unique not null,name text not null,origin text not null default 'team',stage text not null default 'da_contattare',owner_id uuid references public.profiles(user_id),next_action text,next_action_on date,event_starts_on date,event_ends_on date,application_deadline date,research_removed_at timestamptz,created_by uuid references public.profiles(user_id),updated_by uuid references public.profiles(user_id),sections text[],priority text,contact_month date);
create table public.partner_activities(id uuid primary key default gen_random_uuid(),operation_id uuid not null,partner_id uuid not null references public.partners(id),origin text not null default 'team',kind text not null,stage_after text,partner_name text,partner_co integer,message_kind text,occurred_at timestamptz not null default now(),created_by uuid not null references public.profiles(user_id),unique(operation_id,partner_id));
create table public.partner_do_not_contact(partner_id uuid,active boolean not null,reason text,created_by uuid);
create function private.partner_blocked(p_partner_id uuid)returns boolean language sql stable security definer set search_path=''as $$select exists(select 1 from public.partner_do_not_contact where partner_id=p_partner_id and active)$$;
create function private.audit_change_keys()returns trigger language plpgsql security definer set search_path=''as $$begin insert into public.audit_logs(actor_id,table_name,operation,record_key)values(auth.uid(),tg_table_name,tg_op,jsonb_build_object('id',coalesce(to_jsonb(new),to_jsonb(old))->'id'));return coalesce(new,old);end$$;
